#[cfg(test)]
mod raw_catalog_tests {
    use super::*;

    fn command(line: usize) -> RawCommand {
        RawCatalog::builtin()
            .commands
            .into_iter()
            .find(|command| command.reference.id.as_str() == format!("wrynose-6-0.l{line:04}"))
            .unwrap()
    }

    #[test]
    fn raw_catalog_builtin_is_complete_bounded_and_valid() {
        let catalog = RawCatalog::builtin();
        catalog.validate().unwrap();
        assert_eq!(catalog.categories.len(), RAW_BUILTIN_CATEGORY_COUNT);
        assert_eq!(catalog.commands.len(), RAW_BUILTIN_COMMAND_COUNT);
        assert_eq!(
            catalog
                .commands
                .iter()
                .filter(|command| matches!(
                    command.execution,
                    RawExecutionPolicy::Executable { .. }
                ))
                .count(),
            RAW_BUILTIN_EXECUTABLE_COUNT
        );
    }

    #[test]
    fn raw_catalog_preserves_exact_help_and_structured_templates() {
        let task = command(167);
        assert_eq!(task.description, "Execute one named task for a recipe.");
        let RawExecutionPolicy::Executable { template } = task.execution else {
            panic!("task command must execute")
        };
        assert_eq!(
            template.display_template(&task.parameters).as_deref(),
            Some("bitbake -c <task> <recipe>")
        );

        let joined = command(145);
        let RawExecutionPolicy::Executable { template } = joined.execution else {
            panic!("UI command must execute")
        };
        assert!(matches!(
            template.arguments[0],
            RawArgument::JoinedParameter { .. }
        ));

        let composed = command(87);
        let RawExecutionPolicy::Executable { template } = composed.execution else {
            panic!("task syntax must execute")
        };
        assert!(matches!(
            template.arguments[0],
            RawArgument::Composed { .. }
        ));
    }

    #[test]
    fn raw_catalog_marks_interactive_destructive_empty_and_reference_only_entries() {
        let devshell = command(607);
        let RawExecutionPolicy::Executable { template } = devshell.execution else {
            panic!("devshell must execute")
        };
        assert_eq!(template.interaction, RawInteractionMode::InteractivePty);

        let cleanall = command(593);
        let RawExecutionPolicy::Executable { template } = cleanall.execution else {
            panic!("cleanall must execute")
        };
        assert_eq!(template.safety, RawSafetyClass::Destructive);

        let empty_log = command(294);
        let RawExecutionPolicy::Executable { template } = empty_log.execution else {
            panic!("empty event-log argv must execute")
        };
        assert!(template.arguments.contains(&RawArgument::Empty));

        assert!(matches!(
            command(847).execution,
            RawExecutionPolicy::ReferenceOnly {
                kind: RawReferenceKind::ShellPipeline,
                ..
            }
        ));
        assert!(matches!(
            command(1932).execution,
            RawExecutionPolicy::ReferenceOnly {
                kind: RawReferenceKind::CompanionTool,
                ..
            }
        ));
    }

    #[test]
    fn raw_catalog_does_not_present_conceptual_or_companion_sections_as_executable() {
        let catalog = RawCatalog::builtin();
        assert_eq!(
            catalog
                .category(&RawCategoryId::new("section-29-quick-conceptual-reference").unwrap())
                .unwrap()
                .kind,
            RawCategoryKind::Conceptual
        );
        assert_eq!(
            catalog
                .category(&RawCategoryId::new("section-28-yocto-companion-commands").unwrap())
                .unwrap()
                .kind,
            RawCategoryKind::CompanionTools
        );
        assert_eq!(
            catalog
                .category(&RawCategoryId::new("favorites").unwrap())
                .unwrap()
                .kind,
            RawCategoryKind::Favorites
        );
    }
}
